// ---- Circuit (Kit 6) ----
// MQ-2: VCC 5V, GND, AO -> A0 (higher = more gas / smoke)
// Active buzzer + -> D5, - -> GND (HIGH = beep)
#define MQ2_PIN A0
#define BUZZER 5

int level(int pin) {                         // 0-100 %: the MQ modules swing about 0.5 V (clean air) to 4.6 V (heavy gas)
  return constrain(map(analogRead(pin), 100, 920, 0, 100), 0, 100);
}

void setup() {
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int g = level(MQ2_PIN);
  bool leak = g > 40;
  digitalWrite(BUZZER, leak);
  Serial.print("gas level "); Serial.print(g); Serial.println(leak ? " %  LEAK!" : " %  ok");
  delay(300);
}

// ---- Circuit (Kit 6) ----
// Flame sensor: VCC 5V, GND, DO -> D10 (LOW when a flame is seen; the board pot sets the threshold)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Active buzzer + -> D5, - -> GND (HIGH = beep)
#define FLAME_DO 10
#define RED_LED 3
#define BUZZER 5

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool fire = digitalRead(FLAME_DO) == LOW;
  digitalWrite(RED_LED, fire);
  digitalWrite(BUZZER, fire);
  Serial.println(fire ? "FLAME DETECTED" : "no flame");
  delay(250);
}

// ---- Circuit (Kit 6) ----
// MQ-135: VCC 5V, GND, AO -> A1 (higher = worse air)
#define MQ135_PIN A1

int level(int pin) {                         // 0-100 %: the MQ modules swing about 0.5 V (clean air) to 4.6 V (heavy gas)
  return constrain(map(analogRead(pin), 100, 920, 0, 100), 0, 100);
}

void setup() {
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(MQ135_PIN);
  int l = level(MQ135_PIN);
  Serial.print("raw "); Serial.print(raw); Serial.print("  level "); Serial.print(l); Serial.print(" %  -> ");
  if (l < 25) Serial.println("CLEAN");
  else if (l < 50) Serial.println("MODERATE");
  else if (l < 75) Serial.println("POOR");
  else Serial.println("HAZARDOUS");
  delay(500);
}

// ---- Circuit (Kit 6) ----
// DHT22: VCC 5V, GND, DATA -> D7
#define DHT_PIN 7

#include <DHT.h>
DHT dht(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (isnan(t) || isnan(h)) Serial.println("DHT22 read failed - check wiring");
  else { Serial.print("Temperature: "); Serial.print(t, 1); Serial.print(" C   Humidity: "); Serial.print(h, 1); Serial.println(" %"); }
  delay(2000);
}

// ---- Circuit (Kit 6) ----
// DS18B20 probe: VCC 5V, GND, DATA -> D8 with a 10k pull-up from DATA to 5V
#define DS_PIN 8

#include <OneWire.h>
#include <DallasTemperature.h>
OneWire oneWire(DS_PIN);
DallasTemperature ds(&oneWire);

float dsTemp() {                           // degrees C, -127 = sensor not answering
  ds.requestTemperatures();
  return ds.getTempCByIndex(0);
}

void setup() {
  Serial.begin(9600);
  ds.begin();
}

void loop() {
  float t = dsTemp();
  if (t == -127) Serial.println("probe not found - check the DATA wire and the pull-up");
  else { Serial.print("Probe temperature: "); Serial.print(t, 2); Serial.println(" C"); }
  delay(1000);
}

