// ---- Circuit (Kit 6) ----
// Soil moisture probe: VCC 5V, GND, AO -> A3 (dry = high reading)
// Pump: + -> 5V, - -> TIP122 collector; base <- D9 via 1k, emitter -> GND; 1N4007 across the pump (flyback)
// Green LED anode -> 220 ohm -> D4, cathode -> GND
#define SOIL_PIN A3
#define PUMP_PIN 9
#define GREEN_LED 4

int soilPct() { return constrain(map(analogRead(SOIL_PIN), 1023, 0, 0, 100), 0, 100); }     // dry soil reads high

bool pumping = false;
unsigned long lastPrint = 0;

void setup() {
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int m = soilPct();
  if (!pumping && m < 30) { pumping = true; Serial.println("soil dry - pump ON"); }
  if (pumping && m > 50) { pumping = false; Serial.println("soil moist - pump OFF"); }
  digitalWrite(PUMP_PIN, pumping);
  digitalWrite(GREEN_LED, pumping);
  if (millis() - lastPrint > 1000) { lastPrint = millis(); Serial.print("moisture "); Serial.print(m); Serial.println(" %"); }
  delay(50);
}

// ---- Circuit (Kit 6) ----
// Rain sensor: VCC 5V, GND, AO -> A2 (dry = high reading)
// Relay module: DC+ 5V, DC- GND, IN <- D6 (active LOW: LOW = relay on)
// Green LED anode -> 220 ohm -> D4, cathode -> GND
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define RAIN_PIN A2
#define RELAY_PIN 6
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define GREEN_LED 4
#define RED_LED 3

int wetPct() { return constrain(map(analogRead(RAIN_PIN), 1023, 0, 0, 100), 0, 100); }       // dry board reads high

bool closed = false;
unsigned long since = 0;

void setCover(bool c) {
  closed = c;
  digitalWrite(RELAY_PIN, c ? RELAY_ON : RELAY_OFF);
  digitalWrite(RED_LED, c);
  digitalWrite(GREEN_LED, !c);
  Serial.println(c ? "cover CLOSED (rain)" : "cover OPEN");
}

void setup() {
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  setCover(false);
}

void loop() {
  bool raining = wetPct() > 40;
  if (raining == closed) since = millis();                   // nothing to change: restart the 3 s timer
  else if (millis() - since >= 3000) setCover(raining);      // the new condition lasted 3 s
  delay(50);
}

// ---- Circuit (Kit 6) ----
// BMP280: VCC 5V, GND, SDA -> A4, SCL -> A5 (I2C 0x76)
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5 (shared with the BMP280)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D4, cathode -> GND
