}

void loop() {
  bool flame = digitalRead(FLAME_DO) == LOW;
  if (flame && !latched) { latched = true; Serial.println("FIRE! relay cut, siren on"); }
  if (pressed()) {
    if (latched && !flame) { latched = false; Serial.println("alarm reset"); }
    else if (latched) Serial.println("cannot reset: flame still present");
  }
  digitalWrite(RELAY_PIN, latched ? RELAY_ON : RELAY_OFF);
  digitalWrite(RED_LED, latched);
  digitalWrite(BUZZER, latched && (millis() / 300) % 2);                     // siren: on / off
