float offsetSum = 0;
int n = 0;

void setup() {
  Serial.begin(9600);
  ds.begin();
  dht.begin();
  Serial.println("DS18B20, DHT22, difference (DHT - DS), average offset");
}

void loop() {
  float a = dsTemp(), b = dht.readTemperature();
  if (a == -127 || isnan(b)) { Serial.println("a sensor is not answering"); delay(2000); return; }
  float diff = b - a;
  offsetSum += diff; n++;
  Serial.print(a, 2); Serial.print(", "); Serial.print(b, 1); Serial.print(", ");
  Serial.print(diff >= 0 ? "+" : ""); Serial.print(diff, 2); Serial.print(", avg offset ");
  Serial.println(offsetSum / n, 2);
  delay(2000);
}

