  pinMode(BUZZER, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int g = level(MQ2_PIN);
  int now = g >= 75 ? 3 : (g >= 50 ? 2 : (g >= 25 ? 1 : 0));
  if (now != stage) {
    stage = now;
    Serial.print("gas "); Serial.print(g); Serial.print(" % -> ");
    Serial.println(stage == 0 ? "SAFE" : (stage == 1 ? "LOW alarm" : (stage == 2 ? "MEDIUM alarm" : "HIGH alarm")));
  }
  bool beep = false;
  if (stage == 1) beep = (millis() % 1500) < 120;
  if (stage == 2) beep = (millis() % 500) < 150;
  if (stage == 3) beep = true;
  digitalWrite(BUZZER, beep);
  digitalWrite(GREEN_LED, stage == 0);
  digitalWrite(RED_LED, stage > 0);
  delay(10);
}

