int level(int pin) {                         // 0-100 %: the MQ modules swing about 0.5 V (clean air) to 4.6 V (heavy gas)
  return constrain(map(analogRead(pin), 100, 920, 0, 100), 0, 100);
}
int wetPct() { return constrain(map(analogRead(RAIN_PIN), 1023, 0, 0, 100), 0, 100); }       // dry board reads high
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

bool latchGas = false, latchFire = false, latchHot = false, silenced = false;
unsigned long lastDraw = 0;

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  dht.begin();
  lcdBegin();
}

void loop() {
  int gas = level(MQ2_PIN), wet = wetPct();
  bool flame = digitalRead(FLAME_DO) == LOW;
  float t = dht.readTemperature();
  if (gas >= 50 && !latchGas) { latchGas = true; Serial.println("ALARM: gas"); }
  if (flame && !latchFire) { latchFire = true; Serial.println("ALARM: fire"); }
  if (t > 45 && !latchHot) { latchHot = true; Serial.println("ALARM: high temperature"); }
  bool any = latchGas || latchFire || latchHot;
  bool active = gas >= 50 || flame || t > 45;
  if (pressed() && any) {
    if (active) { silenced = true; Serial.println("buzzer silenced (cause still present)"); }
    else { latchGas = latchFire = latchHot = false; silenced = false; Serial.println("alarms reset"); }
  }
  digitalWrite(RELAY_PIN, (latchGas || latchFire) ? RELAY_ON : RELAY_OFF);          // cut-off for gas / fire
  digitalWrite(RED_LED, any);
  digitalWrite(GREEN_LED, !any);
  bool beep = false;
  if (any && !silenced) beep = latchFire ? true : (latchGas ? (millis() % 600) < 300 : (millis() % 1500) < 200);
  digitalWrite(BUZZER, beep);
  if (millis() - lastDraw > 400) {
    lastDraw = millis();
    lcdRow(0, "G" + String(gas) + " F" + (flame ? "!" : "-") + " R" + String(wet) + " T" + String(t, 0));
    String msg = "";
    if (latchGas) msg += "GAS ";
    if (latchFire) msg += "FIRE ";
    if (latchHot) msg += "HOT ";
    lcdRow(1, any ? msg + (silenced ? "(muted)" : "") : (wet > 40 ? "All clear - rain" : "All clear"));
  }
}

