float dsTemp() {                           // degrees C, -127 = sensor not answering
  ds.requestTemperatures();
  return ds.getTempCByIndex(0);
}
int soilPct() { return constrain(map(analogRead(SOIL_PIN), 1023, 0, 0, 100), 0, 100); }     // dry soil reads high

#define NRULES 6
// sensor: 0 soil %, 1 air C, 2 humidity %, 3 root-zone C     compare: 0 = below, 1 = above     action: 0 pump, 1 fan, 2 alert
int RS[NRULES] = {0, 1, 2, 3, 3, 0};
int RC[NRULES] = {0, 1, 1, 0, 1, 1};
float RT[NRULES] = {35, 30, 85, 12, 32, 85};
int RA[NRULES] = {0, 1, 1, 2, 2, 2};
bool active[NRULES], lastActive[NRULES];
float vals[4];
unsigned long lastDraw = 0;

void setup() {
  pinMode(PUMP_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  dht.begin(); ds.begin(); lcdBegin();
  delay(300);                                                 // let the sensors settle before the first rule pass
}

void loop() {
  vals[0] = soilPct(); vals[1] = dht.readTemperature(); vals[2] = dht.readHumidity(); vals[3] = dsTemp();
  bool pump = false, fan = false, alert = false, waterlogged = false;
  for (int i = 0; i < NRULES; i++) {
    float v = vals[RS[i]];
    active[i] = (RC[i] == 0) ? (v < RT[i]) : (v > RT[i]);
    if (active[i] != lastActive[i]) {
      lastActive[i] = active[i];
      Serial.print("rule "); Serial.print(i + 1); Serial.println(active[i] ? " ACTIVE" : " cleared");
    }
    if (active[i] && RA[i] == 0) pump = true;
    if (active[i] && RA[i] == 1) fan = true;
    if (active[i] && RA[i] == 2) alert = true;
  }
  if (active[5]) pump = false;                                // rule 6 (waterlogged soil) inhibits the pump
  digitalWrite(PUMP_PIN, pump);
  digitalWrite(RELAY_PIN, fan ? RELAY_ON : RELAY_OFF);
  if (millis() - lastDraw > 500) {
    lastDraw = millis();
    String list = "";
    for (int i = 0; i < NRULES; i++) if (active[i]) list += String(i + 1) + " ";
    lcdRow(0, String("P:") + (pump ? "on" : "off") + " F:" + (fan ? "on" : "off") + (alert ? " ALERT" : ""));
    lcdRow(1, list == "" ? "no rule active" : "rules " + list);
  }
  delay(100);
}

