int streak = 0;
bool alarm = false;
float tRef = 0;
unsigned long lastSample = 0, lastRef = 0;
int score = 0;

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  dht.begin();
  lcdBegin();
  tRef = dht.readTemperature();
}

void loop() {
  if (millis() - lastRef >= 10000) { lastRef = millis(); tRef = dht.readTemperature(); }
  if (millis() - lastSample >= 1000) {
    lastSample = millis();
    int smoke = level(MQ2_PIN);
    bool flame = digitalRead(FLAME_DO) == LOW;
    float rise = dht.readTemperature() - tRef;
    score = smoke / 2 + (flame ? 40 : 0) + constrain((int)(rise * 10), 0, 30);
    streak = score >= 60 ? streak + 1 : 0;                   // false-alarm suppression: it must persist
    if (streak >= 3 && !alarm) { alarm = true; Serial.println("FIRE ALARM"); }
    Serial.print("score "); Serial.print(score); Serial.print("  (smoke "); Serial.print(smoke); Serial.print(", flame "); Serial.print(flame ? 1 : 0);
    Serial.print(", rise "); Serial.print(rise, 1); Serial.print(")  streak "); Serial.println(streak);
    lcdRow(0, "Score " + String(score));
    lcdRow(1, alarm ? "FIRE ALARM!" : (score >= 30 ? "WATCH" : "normal"));
  }
  if (pressed()) { alarm = false; streak = 0; Serial.println("reset"); }
  digitalWrite(RELAY_PIN, alarm ? RELAY_ON : RELAY_OFF);
  digitalWrite(RED_LED, alarm || (score >= 30 && (millis() / 400) % 2));
  digitalWrite(BUZZER, alarm && (millis() / 250) % 2);
  delay(10);
}

