#define NEV 5
int evPeak[NEV], evDur[NEV], evWho[NEV];          // who: 1 = MQ-135, 2 = MQ-2
int nEv = 0, count = 0, maxPeak = 0, page = 0;
unsigned long totalSec = 0, evStart = 0, lastDraw = 0;
bool inEvent = false;
int curPeak = 0, curWho = 0;

String whoName(int w) { return w == 1 ? "MQ-135" : "MQ-2"; }

void draw() {
  int a = level(MQ135_PIN), b = level(MQ2_PIN);
  if (page == 0) { lcdRow(0, "MQ135 " + String(a) + "%  MQ2 " + String(b) + "%"); lcdRow(1, inEvent ? "EVENT running" : "no event"); }
  if (page == 1) {
    if (nEv == 0) { lcdRow(0, "Last event:"); lcdRow(1, "none yet"); }
    else { lcdRow(0, "Last: " + whoName(evWho[0]) + " " + String(evPeak[0]) + "%"); lcdRow(1, "lasted " + String(evDur[0]) + " s"); }
  }
  if (page == 2) { lcdRow(0, "Events: " + String(count)); lcdRow(1, "peak " + String(maxPeak) + "% tot " + String(totalSec) + "s"); }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  lcdBegin();
  delay(300);
}

void loop() {
  int a = level(MQ135_PIN), b = level(MQ2_PIN);
  int top = max(a, b);
  if (!inEvent && top >= 40) {
    inEvent = true; evStart = millis(); curPeak = top; curWho = a >= b ? 1 : 2;
    digitalWrite(BUZZER, HIGH); delay(100); digitalWrite(BUZZER, LOW);
    Serial.println("event started");
  }
  if (inEvent) {
    if (top > curPeak) { curPeak = top; curWho = a >= b ? 1 : 2; }
    if (top < 30) {
      inEvent = false;
      int dur = (millis() - evStart) / 1000;
      for (int i = NEV - 1; i > 0; i--) { evPeak[i] = evPeak[i - 1]; evDur[i] = evDur[i - 1]; evWho[i] = evWho[i - 1]; }
      evPeak[0] = curPeak; evDur[0] = dur; evWho[0] = curWho;
      if (nEv < NEV) nEv++;
      count++; totalSec += dur; if (curPeak > maxPeak) maxPeak = curPeak;
      Serial.print("event ended: "); Serial.print(whoName(curWho)); Serial.print(" peak "); Serial.print(curPeak); Serial.print(" % for "); Serial.print(dur); Serial.println(" s");
    }
  }
  if (pressed()) { page = (page + 1) % 3; draw(); }
  if (millis() - lastDraw > 400) { lastDraw = millis(); draw(); }
}

