#define WINDOW_MS 15000UL
float ref = 0;
bool dropping = false;
unsigned long refAt = 0, lastDraw = 0;
int lastFactors = -1;

void setup() {
  pinMode(BUZZER, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  dht.begin(); bmpBegin(); lcdBegin();
  ref = bmp.readPressure() / 100.0;
