void loop() {
  if (millis() - refAt >= WINDOW_MS && millis() > 1000) {
    refAt = millis();
    float p = bmp.readPressure() / 100.0;
    dropping = (ref - p) >= 1.5;
    Serial.print("pressure change "); Serial.print(p - ref, 2); Serial.println(" hPa");
    ref = p;
  }
  bool rain = wetPct() > 30;
  bool humid = dht.readHumidity() > 75;
  int factors = (dropping ? 1 : 0) + (rain ? 1 : 0) + (humid ? 1 : 0);
  if (factors != lastFactors) {
    lastFactors = factors;
    Serial.print("factors "); Serial.print(factors); Serial.println(factors == 3 ? " -> STORM WARNING" : (factors == 2 ? " -> STORM WATCH" : " -> calm"));
  }
  digitalWrite(GREEN_LED, factors < 2);
  digitalWrite(RED_LED, factors == 3 ? HIGH : (factors == 2 ? (millis() / 400) % 2 : LOW));
  digitalWrite(BUZZER, factors == 3 && (millis() / 300) % 2);
  if (millis() - lastDraw > 500) {
    lastDraw = millis();
    lcdRow(0, String(dropping ? "P-fall " : "P-ok   ") + (rain ? "RAIN " : "dry ") + (humid ? "HUM" : "hum"));
    lcdRow(1, factors == 3 ? "STORM WARNING!" : (factors == 2 ? "Storm watch" : "Calm"));
  }
  delay(50);
}

