Adafruit_BMP280 bmp;

void bmpBegin() {
  if (!bmp.begin(0x76)) { Serial.println("BMP280 not found - check SDA/SCL"); while (true) { } }
}

unsigned long lastDraw = 0;

bool valid(float t) { return !isnan(t) && t > -20 && t < 60 && t != -127; }

float median3(float a, float b, float c) {
  if ((a >= b && a <= c) || (a <= b && a >= c)) return a;
  if ((b >= a && b <= c) || (b <= a && b >= c)) return b;
  return c;
}

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  dht.begin(); ds.begin(); bmpBegin(); lcdBegin();
  delay(300);
}

void loop() {
  float v[3];
  v[0] = dht.readTemperature(); v[1] = dsTemp(); v[2] = bmp.readTemperature();
  bool ok[3]; bool failed[3];
  int good = 0;
  for (int i = 0; i < 3; i++) { failed[i] = !valid(v[i]); ok[i] = !failed[i]; }
  float ref = 0;
  if (ok[0] && ok[1] && ok[2]) ref = median3(v[0], v[1], v[2]);
  else if (ok[0] || ok[1] || ok[2]) {                         // two or fewer healthy: use their mean as the reference
    float s = 0; int n = 0;
    for (int i = 0; i < 3; i++) if (ok[i]) { s += v[i]; n++; }
    ref = s / n;
  }
  float sum = 0;
  for (int i = 0; i < 3; i++) {
    if (ok[i] && (v[i] - ref > 4 || ref - v[i] > 4) && (ok[0] && ok[1] && ok[2])) ok[i] = false;      // plausibility vote
    if (ok[i]) { sum += v[i]; good++; }
  }
  int raw = analogRead(MQ2_PIN);
  bool mqOk = raw > 20 && raw < 1000;
  String bad = "";
  if (!ok[0]) bad += failed[0] ? "DHT-X " : "DHT? ";
  if (!ok[1]) bad += failed[1] ? "DS-X " : "DS? ";
  if (!ok[2]) bad += failed[2] ? "BMP-X " : "BMP? ";
  if (!mqOk) bad += "MQ2-X";
  bool degraded = bad != "";
  digitalWrite(GREEN_LED, !degraded);
  digitalWrite(RED_LED, degraded);
  if (millis() - lastDraw > 800) {
    lastDraw = millis();
    String t = good > 0 ? String(sum / good, 1) + "C" : "--";
    lcdRow(0, "T " + t + " (" + String(good) + "/3 ok)");
    lcdRow(1, degraded ? bad : "all sensors OK");
    Serial.print("temperature "); Serial.print(t); Serial.print("  healthy "); Serial.print(good); Serial.print("/3  "); Serial.println(degraded ? bad : "OK");
  }
  delay(100);
}

