#define GREEN_LED 4
#define RED_LED 3

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
int wetPct() { return constrain(map(analogRead(RAIN_PIN), 1023, 0, 0, 100), 0, 100); }       // dry board reads high

int tankPct() { return constrain(map(analogRead(SOIL_PIN), 1023, 0, 0, 100), 0, 100); }     // wetter probe = fuller tank

bool inlet = false, pumping = false, locked = false;
int tankAtStart = 0;
unsigned long windowStart = 0, lockedAt = 0, lastDraw = 0;

void setup() {
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  lcdBegin();
  delay(300);
}

void loop() {
  int rain = wetPct(), tank = tankPct();
  bool wantInlet = rain > 30 && tank < 90;
  if (wantInlet != inlet) { inlet = wantInlet; Serial.println(inlet ? "raining: inlet valve OPEN" : "inlet valve closed"); }
  digitalWrite(RELAY_PIN, inlet ? RELAY_ON : RELAY_OFF);

  if (!locked && !pumping && tank > 60) { pumping = true; tankAtStart = tank; windowStart = millis(); Serial.println("tank high - transfer pump ON"); }
  if (pumping && tank < 25) { pumping = false; Serial.println("tank low - pump OFF"); }
  if (pumping && millis() - windowStart > 8000) {
    if (tank > tankAtStart - 3) { pumping = false; locked = true; lockedAt = millis(); Serial.println("DRY-RUN LOCK: the tank is not emptying"); }
    else { tankAtStart = tank; windowStart = millis(); }
  }
  if (locked && millis() - lockedAt > 15000) { locked = false; Serial.println("lock released"); }
  digitalWrite(PUMP_PIN, pumping);
  digitalWrite(GREEN_LED, pumping);
  digitalWrite(RED_LED, locked || tank > 90);
  if (millis() - lastDraw > 500) {
    lastDraw = millis();
    lcdRow(0, "Rain " + String(rain) + "% Tank " + String(tank) + "%");
    lcdRow(1, String(inlet ? "IN:open " : "IN:shut ") + (locked ? "PUMP LOCK" : (pumping ? "PUMP on" : "pump off")));
  }
  delay(50);
}

// ---- Circuit (Kit 6) ----
// Active buzzer + -> D5, - -> GND (HIGH = beep)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D4, cathode -> GND
// Relay module: DC+ 5V, DC- GND, IN <- D6 (active LOW: LOW = relay on)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Flame sensor: VCC 5V, GND, DO -> D10 (LOW when a flame is seen; the board pot sets the threshold)
// MQ-2: VCC 5V, GND, AO -> A0 (higher = more gas / smoke)
#define BUZZER 5
#define RED_LED 3
#define GREEN_LED 4
#define RELAY_PIN 6
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define BTN1 2
#define FLAME_DO 10
#define MQ2_PIN A0

int level(int pin) {                         // 0-100 %: the MQ modules swing about 0.5 V (clean air) to 4.6 V (heavy gas)
  return constrain(map(analogRead(pin), 100, 920, 0, 100), 0, 100);
}
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int level_ = 0, lastLevel = -1;                  // 0 normal, 1 caution, 2 gas, 3 fire
bool acked = false;

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  delay(300);
}

void loop() {
  int gas = level(MQ2_PIN);
  bool flame = digitalRead(FLAME_DO) == LOW;
  level_ = flame ? 3 : (gas >= 50 ? 2 : (gas >= 30 ? 1 : 0));
  if (level_ != lastLevel) {
    if (level_ > lastLevel) acked = false;                    // something worse than before: sound again
    if (level_ == 0) acked = false;
    lastLevel = level_;
    Serial.println(level_ == 3 ? "PRIORITY 1: FIRE" : (level_ == 2 ? "PRIORITY 2: GAS" : (level_ == 1 ? "caution: gas rising" : "normal")));
  }
  if (pressed() && level_ >= 2) { acked = true; Serial.println("acknowledged"); }
  unsigned long ms = millis();
  bool red = false, buz = false, relay = false, green = false;
  if (level_ == 0) green = true;
  if (level_ == 1) green = (ms / 500) % 2;
  if (level_ == 2) { red = (ms / 500) % 2; buz = (ms % 1000) < 120 || (ms % 1000 > 250 && ms % 1000 < 370); relay = (ms / 500) % 2; }
  if (level_ == 3) { red = (ms / 100) % 2; buz = (ms / 150) % 2; relay = true; }
  digitalWrite(RED_LED, red);
  digitalWrite(GREEN_LED, green);
  digitalWrite(BUZZER, buz && !acked);
  digitalWrite(RELAY_PIN, relay ? RELAY_ON : RELAY_OFF);
  delay(10);
}

// ---- Circuit (Kit 6) ----
// DHT22: VCC 5V, GND, DATA -> D7
// DS18B20 probe: VCC 5V, GND, DATA -> D8 with a 10k pull-up from DATA to 5V
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5 (shared with the BMP280)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
// Green LED anode -> 220 ohm -> D4, cathode -> GND
#define DHT_PIN 7
#define DS_PIN 8
#define RED_LED 3
#define GREEN_LED 4

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
#include <DHT.h>
DHT dht(DHT_PIN, DHT22);
#include <OneWire.h>
#include <DallasTemperature.h>
OneWire oneWire(DS_PIN);
DallasTemperature ds(&oneWire);

float dsTemp() {                           // degrees C, -127 = sensor not answering
  ds.requestTemperatures();
  return ds.getTempCByIndex(0);
}

float dewPoint(float t, float h) {              // Magnus approximation
  float a = 17.62, b = 243.12;
  float g = log(h / 100.0) + a * t / (b + t);
  return b * g / (a - g);
}

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  Serial.begin(9600);
  dht.begin(); ds.begin(); lcdBegin();
}

void loop() {
  float t = dht.readTemperature(), h = dht.readHumidity();
  float surface = dsTemp();
  float td = dewPoint(t, h);
  bool dew = (surface - td) <= 2.0;
  bool frost = dew && surface <= 0.0;
  lcdRow(0, "Td " + String(td, 1) + " Surf " + String(surface, 1));
  lcdRow(1, frost ? "FROST RISK!" : (dew ? "DEW RISK" : "Safe, margin " + String(surface - td, 1)));
  digitalWrite(RED_LED, dew);
  digitalWrite(GREEN_LED, !dew);
  Serial.print("air "); Serial.print(t, 1); Serial.print(" C  RH "); Serial.print(h, 0); Serial.print(" %  dew point "); Serial.print(td, 1);
  Serial.print(" C  surface "); Serial.print(surface, 1); Serial.println(frost ? " C  FROST RISK" : (dew ? " C  DEW RISK" : " C  safe"));
  delay(1500);
}

// ---- Circuit (Kit 6) ----
// Pump: + -> 5V, - -> TIP122 collector; base <- D9 via 1k, emitter -> GND; 1N4007 across the pump (flyback)
// Soil moisture probe: VCC 5V, GND, AO -> A3 (dry = high reading)
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5 (shared with the BMP280)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define PUMP_PIN 9
#define SOIL_PIN A3
#define BTN1 2
#define RED_LED 3

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
int soilPct() { return constrain(map(analogRead(SOIL_PIN), 1023, 0, 0, 100), 0, 100); }     // dry soil reads high
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int baseline = 0, runs = 0, lastRise = 0, response = 100;
unsigned long totalSec = 0;
bool clogging = false;

void show() {
  lcdRow(0, "Runs " + String(runs) + " (" + String(totalSec) + " s)");
  lcdRow(1, clogging ? "CLOG PREDICTED!" : (runs == 0 ? "press to water" : "Resp " + String(response) + "% ok"));
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(PUMP_PIN, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  Serial.begin(9600);
  lcdBegin();
  show();
}

void loop() {
  if (pressed()) {
    int before = soilPct();
    Serial.print("run "); Serial.print(runs + 1); Serial.print(": soil before "); Serial.print(before); Serial.println(" %");
    lcdRow(1, "watering...");
    digitalWrite(PUMP_PIN, HIGH);
    delay(5000);
    digitalWrite(PUMP_PIN, LOW);
    delay(500);
    int after = soilPct();
    lastRise = after - before;
    runs++; totalSec += 5;
    if (runs == 1) baseline = max(lastRise, 4);                // the first run is the reference
    response = constrain(lastRise * 100 / baseline, 0, 200);
    clogging = runs > 1 && response < 50;
    Serial.print("  soil after "); Serial.print(after); Serial.print(" %  rise "); Serial.print(lastRise); Serial.print("  response "); Serial.print(response); Serial.println(" % of baseline");
    if (clogging) Serial.println("  PREDICTION: the line is clogging - service the pump");
    digitalWrite(RED_LED, clogging);
    show();
  }
}

// ---- Circuit (Kit 6) ----
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5 (shared with the BMP280)
// MQ-2: VCC 5V, GND, AO -> A0 (higher = more gas / smoke)
// MQ-135: VCC 5V, GND, AO -> A1 (higher = worse air)
// Flame sensor: VCC 5V, GND, DO -> D10 (LOW when a flame is seen; the board pot sets the threshold)
// DHT22: VCC 5V, GND, DATA -> D7
// BMP280: VCC 5V, GND, SDA -> A4, SCL -> A5 (I2C 0x76)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define MQ2_PIN A0
#define MQ135_PIN A1
#define FLAME_DO 10
#define DHT_PIN 7
#define BTN1 2

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
#include <DHT.h>
DHT dht(DHT_PIN, DHT22);
#include <Wire.h>
#include <Adafruit_BMP280.h>
Adafruit_BMP280 bmp;

void bmpBegin() {
  if (!bmp.begin(0x76)) { Serial.println("BMP280 not found - check SDA/SCL"); while (true) { } }
}
int level(int pin) {                         // 0-100 %: the MQ modules swing about 0.5 V (clean air) to 4.6 V (heavy gas)
  return constrain(map(analogRead(pin), 100, 920, 0, 100), 0, 100);
}
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int page = 0;
unsigned long lastDraw = 0;

void draw() {
  int gas = level(MQ2_PIN), air = level(MQ135_PIN);
  int aqi = constrain((air - 10) * 500 / 90, 0, 500);
  bool flame = digitalRead(FLAME_DO) == LOW;
  float t = dht.readTemperature(), h = dht.readHumidity();
  String alert = "";
  if (flame) alert += "FIRE ";
  if (gas >= 50) alert += "GAS ";
  if (aqi > 150) alert += "AIR ";
  if (h > 90) alert += "HUMID";
  String head = alert == "" ? "" : "! " + alert;
  if (page == 0) { lcdRow(0, alert == "" ? "Gas sensors" : head); lcdRow(1, "MQ2 " + String(gas) + "% AQI " + String(aqi)); }
  if (page == 1) { lcdRow(0, alert == "" ? "Flame / status" : head); lcdRow(1, String(flame ? "FLAME!" : "no flame") + (alert == "" ? "  OK" : "  ALERT")); }
  if (page == 2) { lcdRow(0, alert == "" ? "Climate" : head); lcdRow(1, String(t, 1) + "C  " + String(h, 0) + "% RH"); }
  if (page == 3) { lcdRow(0, alert == "" ? "Pressure" : head); lcdRow(1, String(bmp.readPressure() / 100.0, 1) + " hPa"); }
}

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(BTN1, INPUT_PULLUP);
  Serial.begin(9600);
  dht.begin(); bmpBegin(); lcdBegin();
  delay(300);
  draw();
}

void loop() {
  if (pressed()) { page = (page + 1) % 4; draw(); Serial.print("page "); Serial.println(page + 1); }
  if (millis() - lastDraw > 500) { lastDraw = millis(); draw(); }
}

// ---- Circuit (Kit 6) ----
// MQ-2: VCC 5V, GND, AO -> A0 (higher = more gas / smoke)
// MQ-135: VCC 5V, GND, AO -> A1 (higher = worse air)
// Flame sensor: VCC 5V, GND, DO -> D10 (LOW when a flame is seen; the board pot sets the threshold)
// Rain sensor: VCC 5V, GND, AO -> A2 (dry = high reading)
// Soil moisture probe: VCC 5V, GND, AO -> A3 (dry = high reading)
// DHT22: VCC 5V, GND, DATA -> D7
// DS18B20 probe: VCC 5V, GND, DATA -> D8 with a 10k pull-up from DATA to 5V
// BMP280: VCC 5V, GND, SDA -> A4, SCL -> A5 (I2C 0x76)
// Relay module: DC+ 5V, DC- GND, IN <- D6 (active LOW: LOW = relay on)
// Active buzzer + -> D5, - -> GND (HIGH = beep)
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5 (shared with the BMP280)
#define MQ2_PIN A0
#define MQ135_PIN A1
#define FLAME_DO 10
#define RAIN_PIN A2
#define SOIL_PIN A3
#define DHT_PIN 7
#define DS_PIN 8
#define RELAY_PIN 6
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define BUZZER 5

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
void lcdBegin() { lcd.init(); lcd.backlight(); }
#include <DHT.h>
DHT dht(DHT_PIN, DHT22);
#include <OneWire.h>
#include <DallasTemperature.h>
OneWire oneWire(DS_PIN);
DallasTemperature ds(&oneWire);

float dsTemp() {                           // degrees C, -127 = sensor not answering
  ds.requestTemperatures();
  return ds.getTempCByIndex(0);
}
#include <Wire.h>
#include <Adafruit_BMP280.h>
Adafruit_BMP280 bmp;

void bmpBegin() {
  if (!bmp.begin(0x76)) { Serial.println("BMP280 not found - check SDA/SCL"); while (true) { } }
}

int passed = 0, total = 0;
String failures = "";

void report(String name, bool ok) {
  total++;
  if (ok) passed++; else failures += name + " ";
  lcdRow(0, "Check " + String(total) + ": " + name);
  lcdRow(1, ok ? "PASS" : "FAIL");
  Serial.print(name); Serial.println(ok ? ": PASS" : ": FAIL");
  delay(700);
}

void setup() {
  pinMode(FLAME_DO, INPUT);
  pinMode(BUZZER, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  Serial.begin(9600);
  dht.begin(); ds.begin();
  lcdBegin();
  delay(300);
  Serial.println("=== safety self-check ===");
  lcdRow(0, "Self-check"); lcdRow(1, "starting..."); delay(800);
  if (!bmp.begin(0x76)) report("BMP280", false);
  else { float p = bmp.readPressure() / 100.0; report("BMP280", p > 300 && p < 1100); }
  report("MQ-2", analogRead(MQ2_PIN) > 30 && analogRead(MQ2_PIN) < 1000);
  report("MQ-135", analogRead(MQ135_PIN) > 30 && analogRead(MQ135_PIN) < 1000);
  report("FLAME idle", digitalRead(FLAME_DO) == HIGH);
  report("RAIN dry", analogRead(RAIN_PIN) > 600);
  int soil = analogRead(SOIL_PIN);
  report("SOIL", soil > 60 && soil < 1000);
  float t = dht.readTemperature(), h = dht.readHumidity();
  report("DHT22", !isnan(t) && !isnan(h) && t > -20 && t < 60 && h >= 0 && h <= 100);
  float d = dsTemp();
  report("DS18B20", d != -127 && d > -20 && d < 90);
  digitalWrite(RELAY_PIN, RELAY_ON); delay(400); digitalWrite(RELAY_PIN, RELAY_OFF);
  report("RELAY click", true);
  digitalWrite(BUZZER, HIGH); delay(300); digitalWrite(BUZZER, LOW);
  report("BUZZER beep", true);
  Serial.print("RESULT: "); Serial.print(passed); Serial.print("/"); Serial.print(total); Serial.println(passed == total ? " PASS" : " FAIL");
  if (passed != total) { Serial.print("failed: "); Serial.println(failures); }
}

void loop() {
  lcdRow(0, passed == total ? "SELF-CHECK PASS" : "SELF-CHECK FAIL");
  lcdRow(1, String(passed) + "/" + String(total) + (passed == total ? " ok" : " " + failures));
  delay(1000);
}
